    assert!(outcome.is_err());
    assert!(Arc::ptr_eq(runtime.agent.abort_signal.as_ref().unwrap(), &original));
    assert!(Arc::ptr_eq(active.lock().unwrap().as_ref().unwrap(), &original_ui));
}

